from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    store = OrderedDict()  # key -> (value, write_time)
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # remove expired entries lazily check for this key
            if key in store:
                _, wt = store[key]
                if t - wt >= ttl:
                    del store[key]
            if key in store:
                store.move_to_end(key)
                store[key] = (value, t)
            else:
                if len(store) >= capacity:
                    # evict expired entries first if any (optional), but must evict LRU if full
                    # remove any expired entries to free space naturally
                    expired_keys = [k for k, (v, wt) in store.items() if t - wt >= ttl]
                    for k in expired_keys:
                        del store[k]
                    if len(store) >= capacity:
                        store.popitem(last=False)
                store[key] = (value, t)
        else:
            _, t, key = op
            if key in store:
                value, wt = store[key]
                if t - wt >= ttl:
                    del store[key]
                    results.append(-1)
                else:
                    store.move_to_end(key)
                    results.append(value)
            else:
                results.append(-1)
    return results

